-- Rack types move out of device_types into their own table. Ids are kept, so
-- racks.rack_type_id and the rack_type changelog entries stay valid.
CREATE TABLE "rack_types" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "rack_types_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"manufacturer_id" integer NOT NULL,
	"model" text NOT NULL,
	"form_factor" text NOT NULL,
	"width" integer DEFAULT 19 NOT NULL,
	"u_height" integer NOT NULL,
	"part_number" text,
	"spec_url" text,
	"description" text,
	"comments" text
);--> statement-breakpoint
ALTER TABLE "rack_types" ADD CONSTRAINT "rack_types_manufacturer_id_manufacturers_id_fk" FOREIGN KEY ("manufacturer_id") REFERENCES "public"."manufacturers"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "rack_types_manufacturer_id_idx" ON "rack_types" USING btree ("manufacturer_id");--> statement-breakpoint
CREATE INDEX "rack_types_model_idx" ON "rack_types" USING btree ("model");--> statement-breakpoint
CREATE UNIQUE INDEX "rack_types_manufacturer_model_idx" ON "rack_types" USING btree ("manufacturer_id","model");--> statement-breakpoint
-- A type a rack uses may have lost its form factor through the old API. It
-- still has to move, so it falls back to a form factor (now required).
INSERT INTO "rack_types" ("id", "manufacturer_id", "model", "form_factor", "width", "u_height", "part_number", "spec_url", "description", "comments")
SELECT "id", "manufacturer_id", "model", COALESCE("form_factor", '4-post cabinet'), COALESCE("width", 19), "u_height", "part_number", "spec_url", "description", "comments"
FROM "device_types"
WHERE "form_factor" IS NOT NULL
	OR EXISTS (SELECT 1 FROM "racks" WHERE "racks"."rack_type_id" = "device_types"."id");--> statement-breakpoint
SELECT setval(pg_get_serial_sequence('rack_types', 'id'), COALESCE(MAX("id"), 1), MAX("id") IS NOT NULL) FROM "rack_types";--> statement-breakpoint
ALTER TABLE "racks" DROP CONSTRAINT "racks_rack_type_id_device_types_id_fk";--> statement-breakpoint
ALTER TABLE "racks" ADD CONSTRAINT "racks_rack_type_id_rack_types_id_fk" FOREIGN KEY ("rack_type_id") REFERENCES "public"."rack_types"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
-- A moved type that devices were built from stays a device type as well.
DELETE FROM "device_type_interfaces"
WHERE "device_type_id" IN (SELECT "id" FROM "rack_types")
	AND NOT EXISTS (SELECT 1 FROM "devices" WHERE "devices"."device_type_id" = "device_type_interfaces"."device_type_id");--> statement-breakpoint
DELETE FROM "device_types"
WHERE "id" IN (SELECT "id" FROM "rack_types")
	AND NOT EXISTS (SELECT 1 FROM "devices" WHERE "devices"."device_type_id" = "device_types"."id");--> statement-breakpoint
ALTER TABLE "device_types" DROP COLUMN "form_factor";--> statement-breakpoint
ALTER TABLE "device_types" DROP COLUMN "width";
